/// Returns true exactly when one of the four corners points off the grid.
#[verifier(external_body)]
fn check_disconnected(
    n: i8,
    m: i8,
    horizontal: &Vec<char>,
    vertical: &Vec<char>,
) -> bool {
    // Convert to usize for indexing
    let nn: usize = n as usize;
    let mm: usize = m as usize;

    // top‐left corner
    let top_left = horizontal[0] == '>' && vertical[0] == 'v';
    // bottom‐left corner
    let bottom_left = horizontal[0] == '<' && vertical[mm - 1] == 'v';
    // top‐right corner
    let top_right = horizontal[nn - 1] == '>' && vertical[0] == '^';
    // bottom‐right corner
    let bottom_right = horizontal[nn - 1] == '<' && vertical[mm - 1] == '^';

    top_left || bottom_left || top_right || bottom_right
}

/// Produces "NO\n" if the grid is disconnected, "YES\n" otherwise.
#[verifier(external_body)]
fn solve(
    n: i8,
    m: i8,
    horizontal: Vec<char>,
    vertical: Vec<char>,
) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}